package com.nitaaq.map.core.domain

import java.nio.ByteBuffer
import java.nio.charset.CharacterCodingException
import java.nio.charset.CodingErrorAction

/**
 * Kotlin port of `lib/maps-url.ts` from the Nitaaq Map web project.
 *
 * The server (`POST /api/trips`) is the final authority: it re-validates every link with the
 * original TypeScript implementation. This port exists so the app can give instant feedback
 * while typing/pasting, and it is kept behaviour-compatible with the TypeScript version through
 * a shared fixture (`maps_url_cases.json`) generated by `tools/generate-validator-fixtures.mjs`.
 * Keep the two files structurally identical: same helpers, same order of rules.
 */
object MapsLinkValidator {

    // JavaScript's `\s` matches Unicode whitespace; Java's `\s` is ASCII-only, so spell it out.
    private const val JS_WS = "\\s\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF"

    // Optional sign, up to 3 integer digits, optional fraction. Range is checked numerically.
    private const val NUMBER = "-?\\d{1,3}(?:\\.\\d+)?"

    private val coordinatePattern = Regex("^($NUMBER)[$JS_WS]*,[$JS_WS]*($NUMBER)$")

    // The look-arounds stop a pair from being cut out of a longer number ("191,46" -> "91,46").
    private val coordinateSearch = Regex("(?<![\\d.])($NUMBER)[$JS_WS]*,[$JS_WS]*($NUMBER)(?![\\d.])")

    private val bareHostPrefix =
        Regex("^(google\\.com|www\\.google\\.com|maps\\.google\\.com|maps\\.app\\.goo\\.gl|goo\\.gl)/", RegexOption.IGNORE_CASE)

    // Must start at a word boundary of the text, so "notgoogle.com/maps" is not a Google link.
    private val urlSearch = Regex(
        "(?<![A-Za-z0-9._\\-/@=?&%+~#])(https?://)?((www\\.)?google\\.com/maps|maps\\.google\\.com|maps\\.app\\.goo\\.gl|goo\\.gl/maps)[^$JS_WS<>\"']*",
        RegexOption.IGNORE_CASE,
    )
    private val trailingPunctuation = Regex("[)\\].,،]+$")

    // Place pages carry the real pin in their data blob: ...!3d<lat>!4d<lng>...
    private val placeDataCoordinates = Regex("!3d(-?\\d+(?:\\.\\d+)?)!4d(-?\\d+(?:\\.\\d+)?)")
    private val mapViewSegment = Regex("^@(-?\\d+(?:\\.\\d+)?),(-?\\d+(?:\\.\\d+)?)(?:,|$)")

    // RFC 3986, Appendix B.
    private val uriParts = Regex("^([a-zA-Z][a-zA-Z0-9+.-]*):(//([^/?#]*))?([^?#]*)(\\?[^#]*)?(#.*)?$")

    private data class Coordinates(val latitude: String, val longitude: String)

    private fun toCoordinates(latitude: String, longitude: String): Coordinates? {
        val lat = latitude.toDoubleOrNull() ?: return null
        val lng = longitude.toDoubleOrNull() ?: return null
        if (!lat.isFinite() || !lng.isFinite()) return null
        if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return null
        return Coordinates(latitude, longitude)
    }

    private fun parseCoordinates(value: String): Coordinates? {
        val match = coordinatePattern.matchEntire(jsTrim(value)) ?: return null
        return toCoordinates(match.groupValues[1], match.groupValues[2])
    }

    private fun findCoordinates(value: String): Coordinates? =
        coordinateSearch.findAll(value).firstNotNullOfOrNull { toCoordinates(it.groupValues[1], it.groupValues[2]) }

    private fun coordinatesUrl(c: Coordinates) =
        "https://www.google.com/maps/search/?api=1&query=${c.latitude},${c.longitude}"

    private fun directionsUrl(destination: String): String? =
        encodeURIComponent(destination)?.let { "https://www.google.com/maps/dir/?api=1&destination=$it" }

    fun isCoordinates(value: String): Boolean = parseCoordinates(value) != null

    fun coordinateToGoogleMapsUrl(value: String): String {
        val parts = value.split(",").map { jsTrim(it) }
        return coordinatesUrl(Coordinates(parts[0], parts[1]))
    }

    /**
     * Turns whatever the user pasted into the single link a driver should open.
     * Directions links resolve to the FINAL destination, place links keep the place pin.
     */
    fun normalize(value: String): String {
        val trimmed = jsTrim(value)

        parseCoordinates(trimmed)?.let { return coordinatesUrl(it) }

        urlSearch.find(trimmed)?.let { return resolveMapsUrl(it.value.replace(trailingPunctuation, "")) }

        findCoordinates(trimmed)?.let { return coordinatesUrl(it) }

        return trimmed
    }

    private fun resolveMapsUrl(candidate: String): String {
        val url = if (bareHostPrefix.containsMatchIn(candidate)) "https://$candidate" else candidate
        val parts = uriParts.matchEntire(url) ?: return url

        val host = parts.groupValues[3].lowercase()
        if (host == "maps.app.goo.gl" || host == "goo.gl") return url

        val path = parts.groupValues[4]
        val query = parts.groupValues[5]

        val destination = queryParam(query, "destination")?.let { jsTrim(it) }
        if (!destination.isNullOrEmpty()) {
            parseCoordinates(destination)?.let { return coordinatesUrl(it) }
            return directionsUrl(destination) ?: url
        }

        val segments = path.split("/")
        if (segments.getOrElse(1) { "" }.lowercase() == "maps") {
            val rest = segments.drop(2)
            val kind = rest.getOrElse(0) { "" }.lowercase()

            if (kind == "dir") {
                val waypoints = mutableListOf<String>()
                for (segment in rest.drop(1)) {
                    if (segment.startsWith("@") || segment.startsWith("data=")) break
                    val waypoint = jsTrim(decodeComponent(segment))
                    if (waypoint.isNotEmpty()) waypoints += waypoint
                }
                waypoints.lastOrNull()?.let { last ->
                    parseCoordinates(last)?.let { return coordinatesUrl(it) }
                    return directionsUrl(last) ?: url
                }
            }

            if (kind == "place") {
                var pin: Coordinates? = null
                for (match in placeDataCoordinates.findAll(path)) {
                    pin = toCoordinates(match.groupValues[1], match.groupValues[2]) ?: pin
                }
                pin = pin ?: parseCoordinates(decodeComponent(rest.getOrElse(1) { "" }))
                return pin?.let { coordinatesUrl(it) } ?: url
            }

            if (kind == "search") {
                parseCoordinates(decodeComponent(rest.getOrElse(1) { "" }))?.let { return coordinatesUrl(it) }
            }

            mapViewSegment.find(rest.getOrElse(0) { "" })?.let { view ->
                toCoordinates(view.groupValues[1], view.groupValues[2])?.let { return coordinatesUrl(it) }
            }
        }

        val q = queryParam(query, "q") ?: queryParam(query, "query")
        q?.let { parseCoordinates(it) }?.let { return coordinatesUrl(it) }

        return url
    }

    fun isGoogleMapsUrl(value: String): Boolean {
        val trimmed = jsTrim(value)
        if (trimmed.isEmpty()) return false
        if (isCoordinates(trimmed)) return true

        val parsed = parse(normalize(trimmed)) ?: return false
        val host = parsed.host
        val path = parsed.path.lowercase()
        val search = parsed.search.lowercase()

        if (host == "maps.app.goo.gl") return true
        if (host == "goo.gl" && path.startsWith("/maps")) return true

        val isGoogleHost = host == "google.com" ||
            host.endsWith(".google.com") ||
            host == "maps.google.com" ||
            host.endsWith(".maps.google.com")
        if (!isGoogleHost) return false

        return path == "/maps" ||
            path.startsWith("/maps/") ||
            path.contains("/maps") ||
            search.contains("api=1") ||
            search.contains("q=") ||
            search.contains("query=") ||
            search.contains("destination=")
    }

    /** Classifies raw user input for UI messages. */
    fun check(value: String): LinkCheck = when {
        jsTrim(value).isEmpty() -> LinkCheck.Empty
        isGoogleMapsUrl(value) -> LinkCheck.Valid(normalize(value))
        else -> LinkCheck.Invalid
    }

    /** First value of [name] in a raw query string, decoded like URLSearchParams ("+" = space). */
    private fun queryParam(query: String, name: String): String? {
        for (pair in query.removePrefix("?").split("&")) {
            val separator = pair.indexOf('=')
            val key = decodeComponent(if (separator == -1) pair else pair.substring(0, separator))
            if (key == name) return decodeComponent(if (separator == -1) "" else pair.substring(separator + 1))
        }
        return null
    }

    /** JS `decodeURIComponent(value.replace(/\+/g, " "))`, returning the input on malformed escapes. */
    private fun decodeComponent(value: String): String {
        val plusDecoded = value.replace('+', ' ')
        return decodeURIComponent(plusDecoded) ?: plusDecoded
    }

    private fun decodeURIComponent(value: String): String? {
        val out = StringBuilder()
        var i = 0
        while (i < value.length) {
            if (value[i] != '%') {
                out.append(value[i]); i++; continue
            }
            val bytes = java.io.ByteArrayOutputStream()
            while (i < value.length && value[i] == '%') {
                if (i + 3 > value.length) return null
                val hi = Character.digit(value[i + 1], 16)
                val lo = Character.digit(value[i + 2], 16)
                if (hi < 0 || lo < 0 || value[i + 1].code > 127 || value[i + 2].code > 127) return null
                bytes.write(hi * 16 + lo); i += 3
            }
            val decoder = Charsets.UTF_8.newDecoder()
                .onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT)
            try {
                out.append(decoder.decode(ByteBuffer.wrap(bytes.toByteArray())))
            } catch (_: CharacterCodingException) {
                return null
            }
        }
        return out.toString()
    }

    private const val URI_UNRESERVED = "-_.!~*'()"

    /** JS `encodeURIComponent`; null where JS would throw (lone surrogate). */
    private fun encodeURIComponent(value: String): String? {
        val out = StringBuilder()
        var i = 0
        while (i < value.length) {
            val ch = value[i]
            if (ch in 'A'..'Z' || ch in 'a'..'z' || ch in '0'..'9' || ch in URI_UNRESERVED) {
                out.append(ch); i++; continue
            }
            val codePoint: Int
            if (Character.isHighSurrogate(ch)) {
                if (i + 1 >= value.length || !Character.isLowSurrogate(value[i + 1])) return null
                codePoint = Character.toCodePoint(ch, value[i + 1]); i += 2
            } else {
                if (Character.isLowSurrogate(ch)) return null
                codePoint = ch.code; i++
            }
            for (b in String(Character.toChars(codePoint)).toByteArray(Charsets.UTF_8)) {
                out.append('%').append("%02X".format(b.toInt() and 0xFF))
            }
        }
        return out.toString()
    }

    private const val FORBIDDEN_HOST_CHARS = "<>^|\\"

    private data class ParsedUrl(val host: String, val path: String, val search: String)

    /** Minimal WHATWG-like parsing: only what `isGoogleMapsUrl` inspects (host, path, query). */
    private fun parse(candidate: String): ParsedUrl? {
        val match = uriParts.matchEntire(candidate) ?: return null
        val scheme = match.groupValues[1].lowercase()
        if (scheme != "http" && scheme != "https") return null
        if (match.groups[2] == null) return null
        var authority = match.groupValues[3]
        authority = authority.substringAfterLast('@')
        val host = if (authority.startsWith("[")) {
            authority.substringBefore("]") + "]"
        } else {
            val port = authority.substringAfter(':', "")
            if (port.isNotEmpty() && port.any { !it.isDigit() }) return null
            authority.substringBefore(':')
        }.lowercase()
        if (host.isEmpty() || host.any { it in FORBIDDEN_HOST_CHARS || it.isWhitespace() }) return null
        val path = match.groupValues[4].ifEmpty { "/" }
        val query = match.groupValues[5].let { if (it == "?") "" else it }
        return ParsedUrl(host, path, query)
    }

    private fun jsTrim(value: String): String = value.trim { it.isWhitespace() || it == '﻿' || it == ' ' }
}

sealed interface LinkCheck {
    data object Empty : LinkCheck
    data object Invalid : LinkCheck
    data class Valid(val normalizedUrl: String) : LinkCheck
}
